ST.xhtml:p:
IF g_bControlPanelEmergencyStop THEN
  g_boEmergencyStopOut := FALSE;
  g_boCNCMoveDisable := TRUE;
  g_bLaserCuttingEnable := FALSE;
  g_bgas_enable := FALSE;
  g_bLaserDotEnable := FALSE;
  g_bLaserPowerOnEnable := FALSE;
   (*关火,可燃气,助燃气*)
   g_bIgnitionDone := FALSE;
   g_bCombustibleGas_enable := FALSE;
   g_bOxidizingGas_enable := FALSE;
  IF g_nMotionMode=3 OR g_nMotionMode = 5 THEN
    g_boCNCMoveDisable := TRUE;
  END_IF; 
ELSE
  g_boEmergencyStopOut := TRUE;
END_IF;




FOR AxisNum := 0 TO g_nAxisNumber BY 1 DO
  IF g_Alarm.alarmArray[19+AxisNum] <> 0 THEN
    g_boEmergencyStopOut := FALSE;
  END_IF;
END_FOR;
